S.cal=S.cal||[];S.ledger=S.ledger||[];S.ideas=S.ideas||[];S.runs=S.runs||[];S.studio=S.studio||[];S.custom=S.custom||[];S.cdata=S.cdata||{};S.el=S.el||{key:'',voice:''};S.fb=S.fb||'';S.gtts=S.gtts||'gemini-2.5-flash-preview-tts';S.brief=S.brief||null;S.yt=S.yt||{niche:''};
function p2(n){return n<10?'0'+n:''+n}
function ea(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function today(){var d=new Date();return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())}
function mk(id){var s=document.createElement('section');s.className='view';s.id='v-'+id;s.innerHTML='<div class="scroll" id="c-'+id+'"></div>';document.querySelector('main').appendChild(s);return $('#c-'+id)}
function work(el,msg,p){var t=el.textContent;el.disabled=true;el.textContent='⏳ '+msg;return p.then(function(r){el.disabled=false;el.textContent=t;return r},function(e){el.disabled=false;el.textContent=t;alert('Błąd: '+e.message);return null})}
function pj(t){var m=String(t).match(/```(?:json)?\s*([\s\S]*?)```/),s=m?m[1]:String(t),i=s.search(/[\[{]/),j=Math.max(s.lastIndexOf(']'),s.lastIndexOf('}'));if(i<0||j<i)return null;try{return JSON.parse(s.slice(i,j+1))}catch(e){return null}}
function copyTxt(t){try{navigator.clipboard.writeText(t)}catch(e){}}
/* ---- jednorazowe zapytanie do modelu (z modelem zapasowym) ---- */
function once(sys,user,o){o=o||{};var base=o.model||(S.mm&&S.mm[o.mod])||S.model;
 function run(model){var c0=cp(),m=[{role:'system',content:sys},{role:'user',content:user}];
  if(c0)return cfetch(c0,'/chat/completions',{method:'POST',body:{model:model,messages:m}}).then(rj).then(function(j){return j.choices[0].message.content||''});
  if(S.prov==='openai')return jf('https://api.openai.com/v1/chat/completions',{Authorization:'Bearer '+S.key},{model:model,messages:m}).then(function(j){return j.choices[0].message.content||''});
  if(S.prov==='anthropic')return jf('https://api.anthropic.com/v1/messages',{'x-api-key':S.key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'},{model:model,max_tokens:4096,system:sys,messages:[{role:'user',content:user}]}).then(function(j){return j.content.map(function(b){return b.text||''}).join('')});
  var b={systemInstruction:{parts:[{text:sys}]},contents:[{role:'user',parts:[{text:user}]}]};if(o.search)b.tools=[{google_search:{}}];
  return jf('https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent',{'x-goog-api-key':S.key},b).then(function(j){var pr=(j.candidates&&j.candidates[0]&&j.candidates[0].content&&j.candidates[0].content.parts)||[];return pr.map(function(p){return p.text||''}).join('')})}
 if(!S.key&&!srv()&&!cp())return Promise.reject(new Error('Najpierw wpisz klucz API w Ustawieniach'));
 return run(base).catch(function(e){if(S.fb&&S.fb!==base)return run(S.fb);throw e})}
function monthSum(k){k=k||today().slice(0,7);var r={in:0,out:0};S.ledger.forEach(function(x){if(x.d.slice(0,7)===k)r[x.type]+=x.amt});r.in=Math.round(r.in*100)/100;r.out=Math.round(r.out*100)/100;return r}
function lastMonths(n){var o=[],d=new Date();for(var i=n-1;i>=0;i--){var x=new Date(d.getFullYear(),d.getMonth()-i,1),k=x.getFullYear()+'-'+p2(x.getMonth()+1),s=monthSum(k);o.push({k:k,l:p2(x.getMonth()+1),in:s.in,out:s.out})}return o}
function upc(n){var a=today(),e=new Date();e.setDate(e.getDate()+n);var b=e.getFullYear()+'-'+p2(e.getMonth()+1)+'-'+p2(e.getDate());return S.cal.filter(function(x){return x.d>=a&&x.d<=b}).sort(function(x,y){return(x.d+(x.t||'')).localeCompare(y.d+(y.t||''))})}
function evTxt(a){return a.map(function(x){return x.d+(x.t?' '+x.t:'')+' '+x.title}).join('; ')}
function ctx(){var m=S.mem.map(function(x){return x.t}).join('; '),t=S.tasks.filter(function(x){return!x.done}).map(function(x){return x.t}).slice(0,10).join('; '),p=S.proj.map(function(x){return x.n}).join('; '),mo=monthSum();return 'Pamięć o użytkowniku: '+(m||'brak')+'\nOtwarte zadania: '+(t||'brak')+'\nProjekty: '+(p||'brak')+'\nBieżący miesiąc: przychody '+mo.in+' zł, wydatki '+mo.out+' zł.\nNajbliższe wydarzenia: '+(evTxt(upc(7))||'brak')+'\nDziś: '+today()}
function extraCtx(){var u=upc(7);return u.length?'\nNajbliższe wydarzenia w kalendarzu: '+evTxt(u):''}
/* ---- narzędzia asystenta ---- */
function extraTools(){return[
 {name:'add_event',description:'Dodaj wydarzenie do kalendarza użytkownika. date w formacie RRRR-MM-DD, time w formacie GG:MM (opcjonalnie).',p:{title:{type:'string'},date:{type:'string'},time:{type:'string'}},r:['title','date']},
 {name:'add_ledger',description:'Zapisz przychód lub wydatek. type: in (przychód) albo out (wydatek). amount w złotych.',p:{type:{type:'string',enum:['in','out']},amount:{type:'string'},note:{type:'string'}},r:['type','amount']},
 {name:'add_project',description:'Utwórz nowy projekt na liście projektów',p:{name:{type:'string'}},r:['name']}]}
function extraRun(n,a){
 if(n==='add_event'){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(a.date||'')))return Promise.resolve('Zła data, użyj RRRR-MM-DD');S.cal.push({id:uid(),title:String(a.title),d:a.date,t:a.time||''});save();return Promise.resolve('Dodano do kalendarza: '+a.title+' '+a.date+(a.time?' '+a.time:''))}
 if(n==='add_ledger'){var v=parseFloat(String(a.amount).replace(',','.'));if(!(v>0))return Promise.resolve('Zła kwota');S.ledger.unshift({id:uid(),d:today(),type:a.type==='out'?'out':'in',amt:Math.round(v*100)/100,note:a.note||''});save();return Promise.resolve('Zapisano '+(a.type==='out'?'wydatek ':'przychód ')+v+' zł')}
 if(n==='add_project'){S.proj.push({id:uid(),n:String(a.name),note:'',steps:[]});save();return Promise.resolve('Utworzono projekt: '+a.name)}
 return null}
