TABS=[['chat','💬','Czat'],['dash','🏠','Panel'],['money','💰','Money'],['cal','📅','Kalendarz'],['proj','📁','Projekty'],['tasks','✅','Zadania'],['agents','🤖','Agenci'],['studio','🎬','Studio'],['lab','🧪','Warsztat'],['mem','🧠','Pamięć'],['exp','🧬','Eksperci'],['jour','📔','Dziennik'],['cat','📚','Katalog'],['conn','🔌','Połącz'],['imp','✨','Rozwój'],['set','⚙️','Ustaw.']];
