function go(t){document.querySelectorAll('.view').forEach(function(v){v.classList.toggle('on',v.id==='v-'+t)});document.querySelectorAll('nav button').forEach(function(b){b.classList.toggle('on',b.dataset.t===t)});if(R[t])R[t]()}
