function tile(i,v,l,g){return '<div class="tile" data-go="'+g+'"><span>'+i+' '+l+'</span><b>'+ea(v)+'</b></div>'}
function dash(){var open=S.tasks.filter(function(t){return!t.done}),ev=upc(7),ms=monthSum();
 $('#dash').innerHTML='<h2>Dzień dobry 👋</h2><div class="grid2">'+tile('✅',open.length,'zadania','tasks')+tile('📅',ev.length,'wydarzenia (7 dni)','cal')+tile('💰',ms.in+' zł','przychód (mies.)','money')+tile('📈',Math.round((ms.in-ms.out)*100)/100+' zł','bilans (mies.)','money')+'</div>'+
 '<div class="card"><div class="row"><b class="grow">Poranny skrót</b><button class="gh" id="brief">Odśwież</button></div><div class="mut" style="white-space:pre-wrap;margin-top:8px">'+esc(S.brief?S.brief.text:'Kliknij „Odśwież”: asystent przeanalizuje Twoje zadania, kalendarz i pieniądze.')+'</div>'+(S.brief?'<small>'+new Date(S.brief.at).toLocaleString('pl-PL')+'</small>':'')+'</div>'+
 '<div class="card"><b>Asystenci</b><div class="avs" style="border:0;padding:8px 0">'+Object.keys(P).map(function(k){return '<div class="av on" data-k="'+k+'"><div class="orb" style="--c:'+P[k].c+';--d:'+P[k].d+'"></div>'+esc(P[k].n)+'</div>'}).join('')+'</div></div>'+
 '<div class="card"><b>Szybkie akcje</b><div class="chips">'+['Zaplanuj mój dzień','Co zrobić dziś w pierwszej kolejności?','Podsumuj moje zadania','Pomóż mi wymyślić pomysł na dochód'].map(function(q){return '<button class="chip q">'+q+'</button>'}).join('')+'</div></div>'}
$('#dash').onclick=function(e){var t=e.target,g=t.closest('[data-go]'),q=t.closest('.q'),a=t.closest('.av');
 if(t.id==='brief'){work(t,'Piszę…',once((S.intros[S.pers]||P[S.pers].i)+' Napisz zwięzły poranny skrót po polsku (maks. 6 linijek, bez markdownu): priorytety dnia, ryzyka, jedna konkretna rada.',ctx(),{mod:'dash'})).then(function(r){if(r){S.brief={at:Date.now(),text:r.trim()};save();dash()}});return}
 if(g){go(g.dataset.go);return}if(q){go('chat');ask(q.textContent);return}if(a){S.pers=a.dataset.k;save();avs();render();go('chat')}};
/* ---- Money Hunter ---- */
var STG=['Pomysł','Walidacja','Budowa','Start','Przychód'];
function ideaCard(i){return '<div class="card"><div class="row"><b class="grow">'+esc(i.title)+'</b><button class="gh" data-di="'+i.id+'">✕</button></div><p class="mut">'+esc(i.why||'')+'</p>'+(i.steps&&i.steps.length?'<ol style="margin:4px 0 8px 18px;padding:0">'+i.steps.map(function(s){return '<li>'+esc(s)+'</li>'}).join('')+'</ol>':'')+'<small class="mut">Wysiłek: '+esc(i.effort||'?')+' · Potencjał: '+esc(i.potential||'?')+' · Ryzyko: '+esc(i.risk||'?')+'</small><div class="chips">'+STG.map(function(s,k){return '<button class="chip'+((i.stage||0)===k?' on':'')+'" data-ist="'+i.id+'|'+k+'">'+s+'</button>'}).join('')+'</div></div>'}
function money(){var ms=monthSum(),mo=lastMonths(6),mx=Math.max.apply(null,[1].concat(mo.map(function(m){return Math.max(m.in,m.out)})));
 $('#c-money').innerHTML='<h2>💰 Money Hunter</h2><div class="card"><b>Znajdź pomysły na dochód</b><textarea id="mh-pref" rows="2" placeholder="Czas, budżet, umiejętności, zainteresowania (np. 5 h tygodniowo, 0 zł, montaż wideo)"></textarea><label class="mut"><input type="checkbox" id="mh-web" style="width:auto;margin-right:6px">Szukaj aktualnych informacji w sieci (tylko Gemini)</label><br><button class="pri" id="mh-find" style="margin-top:8px">Znajdź pomysły</button><br><small>To propozycje do sprawdzenia, nie obietnica zarobku.</small></div>'+
 S.ideas.map(ideaCard).join('')+
 '<div class="card"><b>Przychody i wydatki</b><div class="row" style="margin-top:6px"><select id="led-type" style="width:auto"><option value="in">Przychód</option><option value="out">Wydatek</option></select><input id="led-amt" type="number" step="0.01" placeholder="Kwota zł"></div><input id="led-note" placeholder="Opis"><button class="pri" id="led-add">Dodaj</button>'+
 '<p class="mut" style="margin:10px 0 4px">Ten miesiąc: przychód <b>'+ms.in+'</b> zł · wydatki <b>'+ms.out+'</b> zł · bilans <b>'+Math.round((ms.in-ms.out)*100)/100+'</b> zł</p>'+
 '<div class="bars">'+mo.map(function(m){return '<div class="bc"><div class="bp"><i style="height:'+(m.in/mx*100)+'%;background:#4ade80"></i><i style="height:'+(m.out/mx*100)+'%;background:#f87171"></i></div><small>'+m.l+'</small></div>'}).join('')+'</div><small>🟩 przychód 🟥 wydatki (ostatnie 6 miesięcy)</small>'+
 S.ledger.slice(0,12).map(function(x){return '<div class="task"><span class="grow">'+x.d+' · '+(x.type==='in'?'+':'−')+x.amt+' zł · '+esc(x.note||'')+'</span><button class="gh" data-dl="'+x.id+'">✕</button></div>'}).join('')+'</div>'}
$('#c-money').onclick=function(e){var t=e.target,d=t.dataset;
 if(t.id==='mh-find'){var web=$('#mh-web').checked&&S.prov==='gemini',pref=$('#mh-pref').value;work(t,'Szukam…',once('Jesteś doradcą ds. dochodów online. Zaproponuj 5 konkretnych, realnych pomysłów dopasowanych do osoby. Nie obiecuj zarobków, oceń uczciwie wysiłek i ryzyko. Zwróć WYŁĄCZNIE JSON: [{"title":"","why":"","steps":["3 do 5 pierwszych kroków"],"effort":"niski|średni|wysoki","potential":"niski|średni|wysoki","risk":""}]','Preferencje: '+pref+'\n'+ctx(),{mod:'money',search:web})).then(function(r){if(!r)return;var a=pj(r);if(!Array.isArray(a)){alert('Nie udało się odczytać odpowiedzi modelu. Spróbuj ponownie.');return}a.slice(0,6).forEach(function(x){if(x&&x.title)S.ideas.unshift({id:uid(),title:String(x.title),why:x.why,steps:Array.isArray(x.steps)?x.steps.map(String):[],effort:x.effort,potential:x.potential,risk:x.risk,stage:0})});logEv('Money Hunter: nowe pomysły na dochód');save();money()});return}
 if(d.ist){var p=d.ist.split('|'),i=S.ideas.filter(function(x){return x.id===p[0]})[0];if(i){i.stage=+p[1];save();money()}return}
 if(d.di){S.ideas=S.ideas.filter(function(x){return x.id!==d.di});save();money();return}
 if(t.id==='led-add'){var a=parseFloat(($('#led-amt').value||'').replace(',','.'));if(!(a>0))return;S.ledger.unshift({id:uid(),d:today(),type:$('#led-type').value,amt:Math.round(a*100)/100,note:$('#led-note').value.trim()});save();money();return}
 if(d.dl){S.ledger=S.ledger.filter(function(x){return x.id!==d.dl});save();money()}};
