var cv={y:new Date().getFullYear(),m:new Date().getMonth(),sel:today()},MN=['Styczeń','Luty','Marzec','Kwiecień','Maj','Czerwiec','Lipiec','Sierpień','Wrzesień','Październik','Listopad','Grudzień'];
function cal(){var f=(new Date(cv.y,cv.m,1).getDay()+6)%7,n=new Date(cv.y,cv.m+1,0).getDate(),h='';
 ['Pn','Wt','Śr','Cz','Pt','So','Nd'].forEach(function(x){h+='<div class="h">'+x+'</div>'});for(var i=0;i<f;i++)h+='<div class="h"></div>';
 for(var d=1;d<=n;d++){var k=cv.y+'-'+p2(cv.m+1)+'-'+p2(d),c=(k===today()?'t ':'')+(k===cv.sel?'s ':'')+(S.cal.some(function(x){return x.d===k})?'d':'');h+='<div class="'+c.trim()+'" data-day="'+k+'">'+d+'</div>'}
 var ev=S.cal.filter(function(x){return x.d===cv.sel}).sort(function(a,b){return(a.t||'').localeCompare(b.t||'')});
 $('#c-cal').innerHTML='<h2>📅 Kalendarz</h2><div class="row"><button class="gh" id="cm-p">◀</button><b class="grow" style="text-align:center">'+MN[cv.m]+' '+cv.y+'</b><button class="gh" id="cm-n">▶</button></div><div class="cal" style="margin:10px 0">'+h+'</div><div class="card"><b>'+cv.sel+'</b>'+(ev.map(function(x){return '<div class="task"><span class="grow">'+esc(x.t||'')+' '+esc(x.title)+'</span><button class="gh" data-de="'+x.id+'">✕</button></div>'}).join('')||'<p class="mut">Brak wydarzeń.</p>')+'<div class="row"><input id="ev-t" class="grow" placeholder="Nowe wydarzenie"><input id="ev-h" type="time" style="width:110px"></div><button class="pri" id="ev-add">Dodaj</button><br><small>Możesz też powiedzieć asystentowi: „dodaj spotkanie jutro o 15:00”.</small></div>'}
$('#c-cal').onclick=function(e){var t=e.target,d=t.dataset;
 if(t.id==='cm-p'){cv.m--;if(cv.m<0){cv.m=11;cv.y--}cal();return}if(t.id==='cm-n'){cv.m++;if(cv.m>11){cv.m=0;cv.y++}cal();return}
 if(d.day){cv.sel=d.day;cal();return}
 if(t.id==='ev-add'){var v=$('#ev-t').value.trim();if(!v)return;S.cal.push({id:uid(),title:v,d:cv.sel,t:$('#ev-h').value||''});logEv('Wydarzenie: '+v+' '+cv.sel);save();cal();return}
 if(d.de){S.cal=S.cal.filter(function(x){return x.id!==d.de});save();cal()}};
