function corpus(){var c=[];if(S.sum)c.push({k:'Streszczenie',t:S.sum});S.mem.forEach(function(m){c.push({k:'Pamięć',t:m.t})});S.tl.forEach(function(x){c.push({k:'Oś czasu '+new Date(x.at).toLocaleDateString('pl-PL'),t:x.t})});
 Object.keys(S.hist).forEach(function(p){S.hist[p].forEach(function(m){if(m.role==='user'||m.role==='assistant')c.push({k:'Rozmowa z '+(P[p]?P[p].n:p)+(m.at?' '+new Date(m.at).toLocaleDateString('pl-PL'):''),t:(m.role==='user'?'Ty: ':'Evoo: ')+m.text})})});
 S.proj.forEach(function(p){c.push({k:'Projekt',t:p.n+' '+(p.note||'')})});S.cal.forEach(function(e){c.push({k:'Kalendarz',t:e.d+' '+e.title})});S.ideas.forEach(function(i){c.push({k:'Pomysł na dochód',t:i.title+' '+(i.why||'')})});
 if(S.jsee!==0)S.jour.forEach(function(e){c.push({k:'Dziennik '+e.d,t:e.text})});return c}
function recall(q,n){var w=words(q);if(!w.length)return[];return corpus().map(function(x){var l=x.t.toLowerCase(),s=0;w.forEach(function(k){if(l.indexOf(k)>=0)s++});return{s:s,x:x}}).filter(function(o){return o.s>0}).sort(function(a,b){return b.s-a.s}).slice(0,n||8).map(function(o){return o.x.k+': '+o.x.t.slice(0,240)})}
var _et2=extraTools;extraTools=function(){return _et2().concat([{name:'recall',description:'Przeszukaj całą pamięć: dawne rozmowy, oś czasu działań, pamięć, projekty, kalendarz, dziennik. Użyj, gdy użytkownik pyta „pamiętasz...”, „co ustaliliśmy”, „kiedy...” albo gdy potrzebujesz kontekstu z przeszłości.',p:{query:{type:'string'}},r:['query']}])};
