/* ===== v9: Eksperci (pomysły, finanse, zdrowie, mechanik, psycholog) + automatyczny dobór ===== */
S.xp=S.xp||[];
var EXB='Odpowiadasz po polsku, konkretnie i uczciwie. Najpierw sedno, potem uzasadnienie i kroki. Wyraźnie oddzielaj fakty od przypuszczeń, podawaj poziom pewności i pytaj o brakujące dane, zamiast zgadywać. Nie zmyślaj liczb, przepisów ani źródeł.';
var EX={
 ideas:{n:'Pomysły',i:'💡',p:'Jesteś kreatywnym strategiem i doradcą biznesowym. Generujesz nieoczywiste, ale wykonalne pomysły, oceniasz je (wysiłek, potencjał, ryzyko), wskazujesz najtańszy sposób sprawdzenia każdego i pierwszy krok na dziś.'},
 fin:{n:'Finanse',i:'💰',p:'Jesteś doradcą finansów osobistych. Pomagasz w budżecie, oszczędzaniu, spłacie długów, planowaniu i podstawach inwestowania, licząc na konkretnych liczbach z danych użytkownika. Zaznacz, że to edukacja, a nie licencjonowane doradztwo inwestycyjne, podatkowe ani prawne; nie obiecuj zysków i przy większych decyzjach zalecaj konsultację z doradcą lub księgowym. Nie polecaj konkretnych papierów wartościowych ani kryptowalut jako pewnej okazji.'},
 health:{n:'Zdrowie',i:'🩺',p:'Jesteś asystentem wiedzy o zdrowiu w roli życzliwego lekarza-edukatora. Wyjaśniasz możliwe przyczyny, co obserwować, co możesz zrobić samemu i kiedy iść do lekarza. NIE stawiasz diagnoz, nie przepisujesz leków ani dawek. Na początku sprawdź objawy alarmowe (ból w klatce piersiowej, duszność, objawy udaru, silne krwawienie, utrata przytomności, myśli samobójcze, silna reakcja alergiczna): jeśli występują, napisz wyraźnie, by dzwonić pod 112. Przy innych sprawach doradź lekarza rodzinnego.'},
 mech:{n:'Mechanik',i:'🔧',p:'Jesteś doświadczonym mechanikiem samochodowym i domowym majsterkowiczem. Diagnozujesz usterki od najprostszej i najtańszej przyczyny do najrzadszej, pytasz o markę, model, rocznik, silnik, objawy i kody błędów, podajesz orientacyjny koszt i czy da się to zrobić samemu. Przy hamulcach, kierownicy, poduszkach, gazie i prądzie wyraźnie ostrzegaj o bezpieczeństwie i zalecaj warsztat.'},
 psy:{n:'Psycholog',i:'🛋️',p:'Jesteś empatycznym towarzyszem refleksji w duchu psychologii (CBT, wartości, uważność). Najpierw wysłuchaj i nazwij emocje, potem zaproponuj perspektywę i mały krok. Nie diagnozujesz i nie zastępujesz terapeuty. Jeśli widać kryzys lub myśli o skrzywdzeniu siebie, napisz z troską o 112 i telefonie wsparcia 800 70 2222 (całodobowo, Polska) oraz o kontakcie z bliską osobą.'}};
var xsel=['auto'];
function expRoute(q){return once('Wybierz 1 do 3 najlepiej pasujących ekspertów do pytania. Dostępni: ideas (pomysły, biznes), fin (finanse), health (zdrowie), mech (mechanik, auto, naprawy), psy (psycholog, emocje, relacje). Zwróć WYŁĄCZNIE JSON: ["klucz",...]',q,{mod:'router'}).then(function(r){var a=pj(r);return Array.isArray(a)?a.filter(function(k){return EX[k]}).slice(0,3):[]}).then(function(a){return a.length?a:['ideas']})}
function expAsk(q,keys,withCtx){var list=keys.map(function(k){return EX[k]});
 var sys=EXB+' '+(list.length===1?list[0].p:'Odpowiedz jako panel ekspertów, każdy w osobnej sekcji z nagłówkiem:\n'+list.map(function(e){return e.n+': '+e.p}).join('\n')+'\nNa końcu dodaj sekcję „Wspólny wniosek i następny krok”.');
 return once(sys,q+(withCtx?'\n\nKontekst o użytkowniku:\n'+ctx()+(S.sum?'\nStreszczenie: '+S.sum:''):''),{mod:'expert'})}
function expv(){var h='<h2>🧬 Eksperci</h2><div class="card"><p class="mut" style="margin:0 0 6px">Jeden mózg, wielu specjalistów. Zostaw „Auto”, a Evoo dobierze ekspertów do pytania, albo wybierz sam.</p><div class="chips"><button class="chip'+(xsel.indexOf('auto')>=0?' on':'')+'" data-xs="auto">✨ Auto</button>'+Object.keys(EX).map(function(k){return '<button class="chip'+(xsel.indexOf(k)>=0?' on':'')+'" data-xs="'+k+'">'+EX[k].i+' '+EX[k].n+'</button>'}).join('')+'</div><textarea id="x-q" rows="4" placeholder="Opisz sprawę: pomysł, pytanie o pieniądze, objaw, usterkę auta, trudną sytuację…"></textarea><label class="mut"><input type="checkbox" id="x-ctx" style="width:auto;margin-right:6px" checked>Użyj mojej pamięci i kontekstu (zadania, finanse, kalendarz)</label><br><button class="pri" id="x-go" style="margin-top:8px">Zapytaj</button><br><small>Zdrowie, finanse i prawo to wiedza ogólna, nie porada profesjonalisty. W nagłych przypadkach dzwoń pod 112.</small></div>';
 h+=S.xp.slice(0,12).map(function(r){return '<div class="card"><div class="row"><b class="grow">'+esc(r.who)+'</b><small>'+new Date(r.at).toLocaleDateString('pl-PL')+'</small><button class="gh" data-xd="'+r.id+'">✕</button></div><small class="mut">'+esc(r.q.slice(0,160))+'</small><div style="white-space:pre-wrap;margin:8px 0">'+esc(r.out)+'</div><div class="row"><button class="gh" data-xc="'+r.id+'">Kopiuj</button><button class="gh" data-xt="'+r.id+'">→ Zadanie</button></div></div>'}).join('');$('#c-exp').innerHTML=h}
$('#c-exp').onclick=function(e){var t=e.target,d=t.dataset;
 if(d.xs){var k=d.xs;if(k==='auto')xsel=['auto'];else{xsel=xsel.filter(function(x){return x!=='auto'});var i=xsel.indexOf(k);if(i>=0)xsel.splice(i,1);else xsel.push(k);if(!xsel.length)xsel=['auto']}var q=$('#x-q').value;expv();$('#x-q').value=q;return}
 if(t.id==='x-go'){var q=$('#x-q').value.trim(),wc=$('#x-ctx').checked;if(!q)return;if(CRI.test(q))alert(HELP);
  work(t,'Myślę…',(xsel.indexOf('auto')>=0?expRoute(q):Promise.resolve(xsel.slice())).then(function(keys){return expAsk(q,keys,wc).then(function(r){return{r:r,keys:keys}})})).then(function(o){if(!o)return;S.xp.unshift({id:uid(),q:q,who:o.keys.map(function(k){return EX[k].i+' '+EX[k].n}).join(' + '),out:o.r.trim(),at:Date.now()});S.xp=S.xp.slice(0,30);logEv('Eksperci: '+o.keys.map(function(k){return EX[k].n}).join(', ')+' - '+q.slice(0,60));save();expv()});return}
 var rec=function(id){return S.xp.filter(function(x){return x.id===id})[0]};
 if(d.xd){S.xp=S.xp.filter(function(x){return x.id!==d.xd});save();expv();return}
 if(d.xc){copyTxt(rec(d.xc).out);t.textContent='Skopiowano';return}
 if(d.xt){S.tasks.unshift({id:uid(),t:rec(d.xt).q.slice(0,120),done:false});save();t.textContent='Dodano'}};
