var _et3=extraTools;extraTools=function(){return _et3().concat([{name:'consult_expert',description:'Skonsultuj się ze specjalistą, gdy pytanie wymaga głębszej wiedzy. domain: ideas (pomysły i biznes), fin (finanse), health (zdrowie), mech (mechanik, auto), psy (psycholog). Zwraca opinię eksperta, którą streszczasz użytkownikowi własnymi słowami, zachowując ostrzeżenia bezpieczeństwa.',p:{domain:{type:'string',enum:['ideas','fin','health','mech','psy']},question:{type:'string',description:'Pełne pytanie z wszystkimi istotnymi szczegółami'}},r:['domain','question']}])};
var _er3=extraRun;extraRun=function(n,a){if(n==='consult_expert'){var k=EX[a.domain]?a.domain:'ideas';return expAsk(String(a.question||''),[k],true).then(function(r){logEv('Konsultacja eksperta: '+EX[k].n);return 'Opinia eksperta ('+EX[k].n+'):\n'+r},function(e){return 'Nie udało się skonsultować: '+e.message})}return _er3(n,a)};
